mapper.select:
select l.id, l.user_id, u.username, u.name, u.dept_id as deptId, d.name as deptName, l.leave_type_id, t.name as leaveTypeName, l.entry_type, l.change_hours, l.business_type, l.business_id, l.operator_user_id, o.name as operatorName, l.remark, l.create_time from attendance_leave_ledger l left join sys_user u on u.id = l.user_id left join sys_dept d on d.id = u.dept_id left join attendance_leave_type t on t.id = l.leave_type_id left join sys_user o on o.id = l.operator_user_id
and l.is_deleted = 0
and l.leave_type_id = #{query.leaveTypeId}
and l.create_time >= #{beginTime}
and l.create_time < #{endExclusive}
and (u.dept_id in
#{deptId}
or l.user_id = #{scope.selfUserId}
)
and l.user_id = #{scope.selfUserId}
and 1 = 0
order by l.create_time desc, l.id desc
